import{_ as o,C as t,o as i,c as r,E as s,a2 as n}from"./chunks/framework.BZ1b3Wf3.js";const _=JSON.parse('{"title":"Cálculo Numérico Interativo – livro com aplicativos no GeoGebra","titleTemplate":false,"description":"Livro gratuito de Cálculo Numérico com aplicativos no GeoGebra para a Licenciatura em Matemática. Ponto flutuante, zeros de funções (bisseção, Newton), sistemas lineares, interpolação, ajuste de curvas, integração numérica e equações diferenciais.","frontmatter":{"title":"Cálculo Numérico Interativo – livro com aplicativos no GeoGebra","titleTemplate":false,"description":"Livro gratuito de Cálculo Numérico com aplicativos no GeoGebra para a Licenciatura em Matemática. Ponto flutuante, zeros de funções (bisseção, Newton), sistemas lineares, interpolação, ajuste de curvas, integração numérica e equações diferenciais.","aside":false,"prev":false,"next":false,"lastUpdated":false,"pageClass":"pagina-painel","head":[["link",{"rel":"canonical","href":"https://osmaralessio.github.io/calculo-numerico/"}]]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),c={name:"index.md"};function l(m,e,u,d,p,f){const a=t("PainelLivro");return i(),r("div",null,[s(a),e[0]||(e[0]=n('<h2 id="apresentacao" tabindex="-1">Apresentação <a class="header-anchor" href="#apresentacao" aria-label="Permalink to &quot;Apresentação&quot;">​</a></h2><p>Este livro reúne textos de Cálculo Numérico preparados para a Licenciatura em Matemática, com uma característica central: cada método é acompanhado de um ou mais aplicativos no GeoGebra, em que o aluno executa o método passo a passo, confere as contas e observa a construção geométrica.</p><p>Os assuntos seguem a ordem usual da disciplina: aritmética de ponto flutuante e erros, zeros de funções, sistemas lineares, interpolação polinomial, ajuste de curvas pelo método dos mínimos quadrados, integração numérica e equações diferenciais ordinárias.</p><p><strong>Como usar.</strong> Os quadros laranja <em>Atividade no GeoGebra</em> trazem o aplicativo do método: clique em <strong>Abrir o aplicativo</strong> e ele aparece ali mesmo, na página. Os quadros verdes <em>Leitura complementar</em> indicam textos de apoio. As respostas dos exercícios ficam no fim de cada capítulo, num quadro que se abre com um clique.</p><p><strong>Autor.</strong> Osmar Alessio, professor da Universidade Federal do Triângulo Mineiro (UFTM), Licenciatura em Matemática – ICENE. Uberaba – MG, 2026.</p>',5))])}const g=o(c,[["render",l]]);export{_ as __pageData,g as default};
